const ARTICLE_MAP = new Map<string, ActivityArticleData>();

JSON_SOURCES.forEach((source) => {
  if (Array.isArray(source)) {
    source.forEach((art) => {
      if (art && art.id) {
        ARTICLE_MAP.set(art.id, art as unknown as ActivityArticleData);
      }
    });
  }
});

export function getArticleById(id: string): ActivityArticleData | null {
  return ARTICLE_MAP.get(id) ?? null;
}

export function getTotalRegisteredArticlesCount(): number {
  return ARTICLE_MAP.size;
}
